import{G as e,b as l,c as r,ae as t}from"./chunks/framework.l_MR1ur9.js";const i="/legacy/images/f709dcb07afa81675711.webp",o="/legacy/images/7916fee0e426825250fd.webp",n="/legacy/images/8186218b61b3dd6326e9.webp",s="/legacy/images/e4109a77aee6ff21b2f6.webp",d="/legacy/images/b86ef233fd7163064004.webp",q=JSON.parse('{"title":"基础篇.1数据库概述与MySQL安装","description":"","frontmatter":{"title":"基础篇.1数据库概述与MySQL安装","date":"2024-01-03 23:30:06","author":"花木凋零成兰","tags":["MySQL"],"categories":["数据库","MySQL"]},"headers":[],"relativePath":"Database/MySQL/基础篇-1数据库概述与MySQL安装.md","filePath":"Database/MySQL/基础篇-1数据库概述与MySQL安装.md","lastUpdated":1791630580000}'),h={name:"Database/MySQL/基础篇-1数据库概述与MySQL安装.md"};function p(c,a,u,b,m,S){return l(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1704324606000"},[...a[0]||(a[0]=[t('<h1 id="基础篇-1数据库概述与mysql安装" tabindex="-1">基础篇.1数据库概述与MySQL安装 <a class="header-anchor" href="#基础篇-1数据库概述与mysql安装" aria-label="Permalink to &quot;基础篇.1数据库概述与MySQL安装&quot;">​</a></h1><h2 id="数据库概述" tabindex="-1">数据库概述 <a class="header-anchor" href="#数据库概述" aria-label="Permalink to &quot;数据库概述&quot;">​</a></h2><h2 id="为什么要使用数据库" tabindex="-1">为什么要使用数据库 <a class="header-anchor" href="#为什么要使用数据库" aria-label="Permalink to &quot;为什么要使用数据库&quot;">​</a></h2><ol><li><p>持久化(persistence)：把<strong>数据保存到可掉电式存储设备中以供之后使用，数据持久化意味着将内存中的数据保存到硬盘上加以“固化”</strong></p></li><li><p>持久化的主要作用是：<strong>将内存中的数据存储在关系型数据库中</strong>，也可以存储在磁盘文件、XML数据文件中。</p></li></ol><p>例子如下：</p><p><img src="'+i+'" alt="image" loading="lazy"></p><h2 id="数据库与数据库管理系统" tabindex="-1">数据库与数据库管理系统 <a class="header-anchor" href="#数据库与数据库管理系统" aria-label="Permalink to &quot;数据库与数据库管理系统&quot;">​</a></h2><h3 id="数据库的相关概念" tabindex="-1">数据库的相关概念 <a class="header-anchor" href="#数据库的相关概念" aria-label="Permalink to &quot;数据库的相关概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>DB</th><th>数据库（Database）</th></tr></thead><tbody><tr><td></td><td>即存储数据的“仓库”，其本质是一个文件系统；保存了一系列有组织的数据</td></tr><tr><td><strong>DBMS</strong></td><td><strong>数据库管理系统</strong>（DataBase Management System）</td></tr><tr><td></td><td>一种操纵和管理数据库的大型软件，用于建立、使用和维护数据库，对数据库进行统一管理和控制；用户通过数据库管理系统访问数据库中表内的数据</td></tr><tr><td><strong>SQL</strong></td><td><strong>结构化查询语言</strong>（Structured Query Language）</td></tr><tr><td></td><td>用来与数据库通信的语言</td></tr></tbody></table><h3 id="数据库与数据库管理系统的关系" tabindex="-1">数据库与数据库管理系统的关系 <a class="header-anchor" href="#数据库与数据库管理系统的关系" aria-label="Permalink to &quot;数据库与数据库管理系统的关系&quot;">​</a></h3><p>数据库管理系统(DBMS)可以管理多个数据库，一般针对一个应用创建一个数据库，为保存应用中实体的数据，一般会在数据库创建多个表，以保存程序中实体用户的数据。</p><p>数据库管理系统、数据库和表的关系如下图所示：</p><p><img src="'+o+'" alt="image" loading="lazy"></p><h3 id="常见的dbms排名" tabindex="-1">常见的DBMS排名 <a class="header-anchor" href="#常见的dbms排名" aria-label="Permalink to &quot;常见的DBMS排名&quot;">​</a></h3><p>目前互联网上常见的数据库管理软件有<strong>Oracle</strong>、<strong>MySQL</strong>、MS SQL Server、DB2、PostgreSQL、Access、Sybase、Informix这几种。</p><p><a href="https://db-engines.com/en/ranking" target="_blank" rel="noreferrer">DB-Engines Ranking</a>：对各数据库受欢迎程度进行调查统计。</p><h3 id="常见的dbms介绍" tabindex="-1">常见的DBMS介绍 <a class="header-anchor" href="#常见的dbms介绍" aria-label="Permalink to &quot;常见的DBMS介绍&quot;">​</a></h3><h4 id="oracle" tabindex="-1">Oracle <a class="header-anchor" href="#oracle" aria-label="Permalink to &quot;Oracle&quot;">​</a></h4><p>1979 年，Oracle 2 诞生，它是第一个商用的 RDBMS（关系型数据库管理系统）。随着 Oracle 软件的名气越来越大，公司也改名叫 Oracle 公司。 2007年，总计85亿美金收购BEA Systems。 2009年，总计74亿美金收购SUN。此前的2008年，SUN以10亿美金收购MySQL。意味着Oracle 同时拥有了MySQL 的管理权，至此 Oracle 在数据库领域中成为绝对的领导者。 2013年，甲骨文超越IBM，成为继Microsoft后全球第二大软件公司。 如今 Oracle 的年收入达到了 400 亿美金，足以证明商用（收费）数据库软件的价值。</p><h4 id="sql-server" tabindex="-1">SQL Server <a class="header-anchor" href="#sql-server" aria-label="Permalink to &quot;SQL Server&quot;">​</a></h4><p>SQL Server 是微软开发的大型商业数据库，诞生于 1989 年。C#、.net等语言常使用，与WinNT完全集成，也可以很好地与Microsoft BackOffice产品集成。</p><h4 id="db2" tabindex="-1">DB2 <a class="header-anchor" href="#db2" aria-label="Permalink to &quot;DB2&quot;">​</a></h4><p>IBM公司的数据库产品,收费的。常应用在银行系统中。</p><h4 id="postgresql" tabindex="-1">PostgreSQL <a class="header-anchor" href="#postgresql" aria-label="Permalink to &quot;PostgreSQL&quot;">​</a></h4><p>PostgreSQL 的稳定性极强，最符合SQL标准，开放源码，具备商业级DBMS质量。PG对数据量大的文本以及SQL处理较快。</p><h4 id="sqlite" tabindex="-1">SQLite <a class="header-anchor" href="#sqlite" aria-label="Permalink to &quot;SQLite&quot;">​</a></h4><p>嵌入式的小型数据库，应用在手机端。 零配置，SQlite3不用安装，不用配置，不用启动，关闭或者配置数据库实例。当系统崩溃后不用做任何恢复操作，再下次使用数据库的时候自动恢复。</p><h4 id="informix" tabindex="-1">informix <a class="header-anchor" href="#informix" aria-label="Permalink to &quot;informix&quot;">​</a></h4><p>IBM公司出品，取自Information 和Unix的结合，它是第一个被移植到Linux上的商业数据库产品。仅运行于unix/linux平台，命令行操作。 性能较高，支持集群，适应于安全性要求极高的系统，尤其是银行，证券系统的应用。</p><h2 id="mysql介绍" tabindex="-1">MySQL介绍 <a class="header-anchor" href="#mysql介绍" aria-label="Permalink to &quot;MySQL介绍&quot;">​</a></h2><h3 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h3><ul><li><p>MySQL是一个<code>开放源代码的关系型数据库管理系统</code>，由瑞典MySQL AB（创始人Michael Widenius）公司1995年开发，迅速成为开源数据库的 No.1。</p></li><li><p>2008被Sun 收购（10亿美金），2009年Sun被Oracle 收购。MariaDB 应运而生。（MySQL 的创造者担心 MySQL 有闭源的风险，因此创建了 MySQL 的分支项目 MariaDB）</p></li><li><p>MySQL6.x 版本之后分为社区版和商业版。</p></li><li><p>MySQL是一种关联数据库管理系统，将数据保存在不同的表中，而不是将所有数据放在一个大仓库内，这样就增加了速度并提高了灵活性。</p></li><li><p>MySQL是开源的，所以你不需要支付额外的费用。</p></li><li><p>MySQL是可以定制的，采用了GPL（GNU General Public License） 协议，你可以修改源码来开发自己的MySQL系统。</p></li><li><p>MySQL支持大型的数据库。可以处理拥有上千万条记录的大型数据库。</p></li><li><p>MySQL支持大型数据库，支持5000万条记录的数据仓库，32位系统表文件最大可支持4GB ，64位系统支持最大的表文件为8TB 。</p></li><li><p>MySQL使用<code>标准的SQL数据语言</code>形式。</p></li><li><p>MySQL可以允许运行于多个系统上，并且支持多种语言。这些编程语言包括C、C++、Python、Java、Perl、PHP和Ruby等。</p></li></ul><h3 id="mysql发展史重大事件" tabindex="-1">MySQL发展史重大事件 <a class="header-anchor" href="#mysql发展史重大事件" aria-label="Permalink to &quot;MySQL发展史重大事件&quot;">​</a></h3><p>MySQL的历史就是整个互联网的发展史。互联网业务从社交领域、电商领域到金融领域的发展，推动着应用对数据库的需求提升，对传统的数据库服务能力提出了挑战。高并发、高性能、高可用、轻资源、易维护、易扩展的需求，促进了MySQL的长足发展。</p><p>发展历程思维导图如下：</p><p><a href="https://github.com/YTAZWC/picx-images-hosting/raw/master/%E5%B0%9A%E7%A1%85%E8%B0%B7MySQL%E5%85%A5%E9%97%A8%E5%88%B0%E9%AB%98%E7%BA%A7_%E5%9F%BA%E7%A1%80%E7%AF%87/image.4gio790nsye0.webp" target="_blank" rel="noreferrer">https://github.com/YTAZWC/picx-images-hosting/raw/master/尚硅谷MySQL入门到高级_基础篇/image.4gio790nsye0.webp</a></p><h3 id="关于mysql-8-0" tabindex="-1">关于MySQL 8.0 <a class="header-anchor" href="#关于mysql-8-0" aria-label="Permalink to &quot;关于MySQL 8.0&quot;">​</a></h3><p><strong>MySQL从5.7版本直接跳跃发布了8.0版本</strong></p><p>MySQL 8版本在功能上做了显著的改进与增强，开发者对MySQL的源代码进行了重构，最突出的一点是多MySQL Optimizer优化器进行了改进。不仅在速度上得到了改善，还为用户带来了更好的性能和更棒的体验。</p><h3 id="为什么很多厂商选择mysql" tabindex="-1">为什么很多厂商选择MySQL <a class="header-anchor" href="#为什么很多厂商选择mysql" aria-label="Permalink to &quot;为什么很多厂商选择MySQL&quot;">​</a></h3><ol><li>开放源代码，使用成本低。</li><li>性能卓越，服务稳定。</li><li>软件体积小，使用简单，并且易于维护。</li><li>历史悠久，社区用户非常活跃，遇到问题可以寻求帮助。</li><li>许多互联网公司在用，经过了时间的验证。</li></ol><h3 id="oracle-vs-mysql" tabindex="-1">Oracle vs MySQL <a class="header-anchor" href="#oracle-vs-mysql" aria-label="Permalink to &quot;Oracle vs MySQL&quot;">​</a></h3><p>Oracle 更适合大型跨国企业的使用，因为他们对费用不敏感，但是对性能要求以及安全性有更高的要求。</p><p>MySQL 由于其<strong>体积小、速度快、总体拥有成本低，可处理上千万条记录的大型数据库，尤其是开放源码这一特点，使得很多互联网公司、中小型网站选择了MySQL作为网站数据库</strong>（Facebook，Twitter，YouTube，阿里巴巴/蚂蚁金服，去哪儿，美团外卖，腾讯）。</p><h2 id="rdbms-与-非rdbms" tabindex="-1">RDBMS 与 非RDBMS <a class="header-anchor" href="#rdbms-与-非rdbms" aria-label="Permalink to &quot;RDBMS 与 非RDBMS&quot;">​</a></h2><p>从排名中我们能看出来，关系型数据库绝对是DBMS的主流，其中使用最多的DBMS分别是Oracle、MySQL和SQL Server，这些都是关系型数据库（RDBMS）</p><h3 id="关系型数据库-rdbms" tabindex="-1">关系型数据库(RDBMS) <a class="header-anchor" href="#关系型数据库-rdbms" aria-label="Permalink to &quot;关系型数据库(RDBMS)&quot;">​</a></h3><h4 id="实质" tabindex="-1">实质 <a class="header-anchor" href="#实质" aria-label="Permalink to &quot;实质&quot;">​</a></h4><ul><li><p>这种类型的数据库是<code>最古老</code>的数据库类型，关系型数据库模型是把复杂的数据结构归结为简单的<code>二元关系</code>（即二维表格形式）。</p></li><li><p>关系型数据库以<code>行(row)</code>和<code>列(column)</code>的形式存储数据，以便于用户理解。这一系列的行和列被称为<code>表</code>，一组组成了一个库(database)</p></li><li><p>表与表之间的数据记录有关系(relationship)，现实世界中的各种实体以及实体之间的各种联系均用<strong>关系模型</strong>来表示。关系型数据库，建立在<strong>关系模型</strong>基础上的数据库。</p></li><li><p>SQL就是关系型数据库的查询语言。</p></li></ul><h4 id="优势" tabindex="-1">优势 <a class="header-anchor" href="#优势" aria-label="Permalink to &quot;优势&quot;">​</a></h4><ul><li><p><strong>复杂查询</strong> 可以用SQL语句方便在一个表以及多个表之间做非常复杂的数据查询。</p></li><li><p><strong>事务支持</strong> 是的对于安全性能很高的数据访问要求得以实现。</p></li></ul><h3 id="非关系型数据库-非rdbms" tabindex="-1">非关系型数据库(非RDBMS) <a class="header-anchor" href="#非关系型数据库-非rdbms" aria-label="Permalink to &quot;非关系型数据库(非RDBMS)&quot;">​</a></h3><h4 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h4><p><strong>非关系型数据</strong>，看成传统关系型数据库的功能阉割版本，基于键值对存储数据，不需要经过SQL层的解析，性能非常高。同时，减少不常用的功能，来进一步提高性能。</p><h4 id="有哪些-非rdbms" tabindex="-1">有哪些 非RDBMS <a class="header-anchor" href="#有哪些-非rdbms" aria-label="Permalink to &quot;有哪些 非RDBMS&quot;">​</a></h4><p>相比于 SQL，NoSQL 泛指非关系型数据库，包括了榜单上的键值型数据库、文档型数据库、搜索引擎和列存储等，除此以外还包括图形数据库。也只有用 NoSQL 一词才能将这些技术囊括进来。</p><h5 id="键值型数据库" tabindex="-1">键值型数据库 <a class="header-anchor" href="#键值型数据库" aria-label="Permalink to &quot;键值型数据库&quot;">​</a></h5><ul><li><p>通过Key-Value键值方式来存储数据，其中key和Value可以是简单的对象，也可以是复杂的对象。</p></li><li><p>Key 作为唯一的标识符，优点是查找速度快，明显优于关系型数据库，缺点是无法像关系型数据库一样使用条件过滤 (比如WHERE)</p></li><li><p>容易出现不知道去哪里找数据，要遍历所有键，会消耗大量的计算问题。</p></li></ul><p>键值型数据库的典型使用场景：<strong>内存缓存</strong>。<code>Redis</code>是最流行的键值型数据库。</p><h5 id="文档型数据库" tabindex="-1">文档型数据库 <a class="header-anchor" href="#文档型数据库" aria-label="Permalink to &quot;文档型数据库&quot;">​</a></h5><p>此类数据库可存放并获取文档，可以是XML、JSON等格式。在数据库中文档作为处理信息的基本单位，一个文档就相当于一条记录。文档数据库所存放的文档，就相当于键值数据库所存放的“值”。</p><p>MongoDB是最流行的文档型数据库。此外，还有CouchDB等。</p><h5 id="搜索引擎数据库" tabindex="-1">搜索引擎数据库 <a class="header-anchor" href="#搜索引擎数据库" aria-label="Permalink to &quot;搜索引擎数据库&quot;">​</a></h5><p>虽然关系型数据库采用了索引提升检索效率，但是针对全文索引效率却较低。搜索引擎数据库是应用在搜索引擎领域的数据存储形式，由于搜索引擎会爬取大量的数据，并以特定的格式进行存储，这样在检索的时候才能保证性能最优。核心原理是 <strong>“倒排索引”</strong>。</p><p>典型产品：Solr、Elasticsearch、Splunk 等</p><h5 id="列式数据库" tabindex="-1">列式数据库 <a class="header-anchor" href="#列式数据库" aria-label="Permalink to &quot;列式数据库&quot;">​</a></h5><p>列式数据库是相对于行式存储的数据库，Oracle、MySQL、SQL Server 等数据库都是采用的行式存储（Row-based），而列式数据库是将数据按照列存储到数据库中，这样做的好处是<strong>可以大量降低系统的I/O，适合于分布式文件系</strong>统，不足在于功能相对有限。</p><p>典型产品：HBase等。</p><h5 id="图形数据库" tabindex="-1">图形数据库 <a class="header-anchor" href="#图形数据库" aria-label="Permalink to &quot;图形数据库&quot;">​</a></h5><p>图形数据库，利用了图这种数据结构存储了实体（对象）之间的关系。图形数据库最典型的例子就是社交网络中人与人的关系，数据模型主要是以节点和边（关系）来实现，特点在于能高效地解决复杂的关系问题。</p><p>图形数据库顾名思义，就是一种存储图形关系的数据库。它利用了图这种数据结构存储了实体（对象）之间的关系。</p><p>关系型数据用于存储明确关系的数据，但对于复杂关系的数据存储却有些力不从心。如社交网络中人物之间的关系，如果用关系型数据库则非常复杂，用图形数据库将非常简单。</p><p>典型产品：Neo4J、InfoGrid等。</p><h4 id="nosql的演变" tabindex="-1">NoSQL的演变 <a class="header-anchor" href="#nosql的演变" aria-label="Permalink to &quot;NoSQL的演变&quot;">​</a></h4><p>NoSQL对SQL做出了很好的补充，比如实际开发中，有很多业务需求，其实并不需要完整的关系型数据库功能，非关系型数据库的功能就足够使用了。这种情况下，使用<strong>性能更高</strong>、<strong>成本更低</strong>的非关系型数据库当然是更明智的选择。</p><p>比如：日志收集、排行榜、定时器等。</p><h2 id="关系型数据库设计规则" tabindex="-1">关系型数据库设计规则 <a class="header-anchor" href="#关系型数据库设计规则" aria-label="Permalink to &quot;关系型数据库设计规则&quot;">​</a></h2><ul><li><p>关系型数据库的典型数据结构就是 <code>数据表</code>，这些数据表的组成都是结构化的(Structured)</p></li><li><p>将数据放到表中，表再放到库中。</p></li><li><p>一个数据库中有多个表，每个表都有一个名字，用来标识自己。表名具有唯一性。</p></li><li><p>表具有一些特性，这些特性定义了数据在表中如何存储，类似Java和Python中 “类”的设计。</p></li></ul><h3 id="表、记录、字段" tabindex="-1">表、记录、字段 <a class="header-anchor" href="#表、记录、字段" aria-label="Permalink to &quot;表、记录、字段&quot;">​</a></h3><ul><li><p>E-R（entity-relationship, 实体-联系）模型中三个主要概念：<code>实体集</code>、<code>属性</code>、<code>联系集</code></p></li><li><p>一个实体集（class）对应于数据库中的一个表（table）</p></li><li><p>一个实体（instance）则对应于数据库表中的一行（row），也称为一条记录（record）。</p></li><li><p>一个属性（attribute）对应于数据库表中的一列（column），也称为一个字段（field）</p></li></ul><p><strong>ORM思想</strong>：</p><ul><li><p>数据库中一个表 &lt;===&gt; Java或Python中的一个类</p></li><li><p>表中一条数据 &lt;===&gt; 类的实体</p></li><li><p>表中的一个列 &lt;===&gt; 类中的一个字段、属性(field)</p></li></ul><h3 id="表的关系关系" tabindex="-1">表的关系关系 <a class="header-anchor" href="#表的关系关系" aria-label="Permalink to &quot;表的关系关系&quot;">​</a></h3><ul><li>表语表之间的数据记录有关系，现实世界中的各种实体以及实体之间的各种联系均用关系模型来表示。</li></ul><h4 id="一对一关联-one-to-one" tabindex="-1">一对一关联(one-to-one) <a class="header-anchor" href="#一对一关联-one-to-one" aria-label="Permalink to &quot;一对一关联(one-to-one)&quot;">​</a></h4><ul><li><p>实际开发应用不多，因为一对一可以创建成一张表</p></li><li><p>举例：设计<code>学生表</code>：学号、姓名、手机号码、班级、系别、身份证号码、家庭住址、籍贯、紧急联系人、...</p><ul><li><p>拆为两个表：两个表的记录是一一对应关系。</p></li><li><p><code>基础信息表</code>（常用信息）：学号、姓名、手机号码、班级、系别</p></li><li><p><code>档案信息表</code>（不常用信息）：学号、身份证号码、家庭住址、籍贯、紧急联系人、...</p></li></ul></li><li><p>两种建表原则：</p><ul><li><p>外键唯一：主表的主键和从表的外键（唯一），形成主外键关系，外键唯一。</p></li><li><p>外键是主键：主表的主键和从表的主键，形成主外键关系。</p></li></ul></li></ul><p>具体例子如下图：</p><p><img src="'+n+'" alt="image" loading="lazy"></p><h4 id="一对多关系-one-to-many" tabindex="-1">一对多关系(one-to-many) <a class="header-anchor" href="#一对多关系-one-to-many" aria-label="Permalink to &quot;一对多关系(one-to-many)&quot;">​</a></h4><ul><li><p>常见实例场景： <code>客户表和订单表</code>， <code>分类表和商品表</code>， <code>部门表和员工表</code>。</p></li><li><p>举例：</p><ul><li><p>员工表：编号、姓名、...、所属部门</p></li><li><p>部门表：(部门)编号、名称、简介</p></li></ul></li><li><p>一对多建表原则：在从表(多方)创建一个字段，字段作为外键指向主表(一方)的主键</p></li></ul><p><img src="'+s+'" alt="image" loading="lazy"></p><h4 id="多对多-many-to-many" tabindex="-1">多对多(many-to-many) <a class="header-anchor" href="#多对多-many-to-many" aria-label="Permalink to &quot;多对多(many-to-many)&quot;">​</a></h4><p>要<strong>表示多对多关系，必须创建第三个表</strong>，该表通常称为<code>联接表</code>，它将多对多关系划分为两个一对多关系。将这两个表的主键都插入到第三个表中。</p><ul><li><p>举例：学生-课程</p><ul><li><p><code>学生信息表</code>：一行代表一个学生的信息（学号、姓名、手机号码、班级、系别...）</p></li><li><p><code>课程信息表</code>：一行代表一个课程的信息（课程编号、授课老师、简介...）</p></li><li><p><code>选课信息表</code>：一个学生可以选多门课，一门课可以被多个学生选择</p></li></ul></li></ul><h4 id="自我引用-self-reference" tabindex="-1">自我引用(Self reference) <a class="header-anchor" href="#自我引用-self-reference" aria-label="Permalink to &quot;自我引用(Self reference)&quot;">​</a></h4><p>如下图所示：</p><p><img src="'+d+'" alt="image" loading="lazy"></p><h2 id="mysql环境搭建" tabindex="-1">MySQL环境搭建 <a class="header-anchor" href="#mysql环境搭建" aria-label="Permalink to &quot;MySQL环境搭建&quot;">​</a></h2><h2 id="停止mysql服务" tabindex="-1">停止MySQL服务 <a class="header-anchor" href="#停止mysql服务" aria-label="Permalink to &quot;停止MySQL服务&quot;">​</a></h2><p>先停止MySQL8.0的服务。按键盘上的“Ctrl + Alt + Delete”组合键，打开“任务管理器”对话 框，可以在“服务”列表找到“MySQL8.0”的服务，如果现在“正在运行”状态，可以右键单击服务，选择“停止”选项停止MySQL8.0的服务，如图所示</p>',100)])])}const g=e(h,[["render",p]]);export{q as __pageData,g as default};
